parameters.query:
SELECT COALESCE((
  SELECT decrypted_secret FROM vault.decrypted_secrets
   WHERE name = 'overname_webhook_token' LIMIT 1
), '') AS overname_token;

parameters.jsCode:
// Shared-secret gate + input validation for the order handover door.
// The secret lives in Vault (overname_webhook_token), not in this code: shipday_compensate
// reads its keys the same way. shipday_webhook_status still hardcodes its secret - do not
// copy that half of the pattern.
const secret = $input.first().json.overname_token || '';
const hook = $('Overname Webhook').first().json;
const headers = hook.headers || {};
const body = hook.body || {};
const token = headers['x-overname-token'] || '';

if (!secret) throw new Error('overname_webhook_token missing from vault');
if (token !== secret) throw new Error('unauthorized');

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const LOC = /^LOC_[A-Z0-9_]{1,32}$/;
// Rides into external_ref and onto the printed ticket, so keep it short and plain.
const NAAM = /^[A-Z0-9 _-]{1,24}$/;

const action = String(body.action || '');
const canonicalId = String(body.canonical_id || '');
if (!UUID.test(canonicalId)) throw new Error('canonical_id is not a uuid');

if (action === 'check') {
  const kandidaten = Array.isArray(body.location_keys) ? body.location_keys.map(String) : [];
  if (!kandidaten.length) throw new Error('location_keys is empty');
  for (const k of kandidaten) if (!LOC.test(k)) throw new Error('bad location_key: ' + k);
  return [{ json: { action, canonical_id: canonicalId, location_keys: kandidaten } }];
}

if (action === 'move') {
  const target = String(body.target_location_key || '');
  const van = String(body.van_naam || '').toUpperCase();
  if (!LOC.test(target)) throw new Error('bad target_location_key');
  if (!NAAM.test(van)) throw new Error('bad van_naam');
  return [{ json: { action, canonical_id: canonicalId, target_location_key: target, van_naam: van } }];
}

throw new Error('unknown action: ' + action);

// The move node carries alwaysOutputData, so an empty result arrives here as one empty item
// instead of skipping this node. That is the point: no row means the cancel matched nothing -
// the order was already cancelled, already complete, or ls_rejected. A silent 200 there would
// leave the OS believing a till printed.
const rows = $input.all().filter(r => r.json && r.json.canonical_id);
if (!rows.length) {
  throw new Error('order not movable: it is already cancelled, complete or ls_rejected');
}
return rows;
